$ErrorActionPreference='Stop'
$out=Split-Path -Parent $MyInvocation.MyCommand.Path; $root=Split-Path -Parent $out
$docx=Join-Path $out 'Samay_Final_Project_Report.docx'; $pdf=Join-Path $out 'Samay_Final_Project_Report.pdf'
Write-Host "Generating report to $out"
$W=New-Object -ComObject Word.Application; $W.Visible=$false; $D=$W.Documents.Add(); $S=$D.Sections.Item(1)
$S.PageSetup.TopMargin=$W.InchesToPoints(.85); $S.PageSetup.BottomMargin=$W.InchesToPoints(.75); $S.PageSetup.LeftMargin=$W.InchesToPoints(1); $S.PageSetup.RightMargin=$W.InchesToPoints(.8); $S.PageSetup.DifferentFirstPageHeaderFooter=$true
$h=$S.Headers.Item(1).Range; $h.Text='SAMAY: MOBILE STUDY PRODUCTIVITY AND GROUP COLLABORATION PLATFORM'; $h.Font.Name='Times New Roman';$h.Font.Size=8;$h.ParagraphFormat.Alignment=1
$f=$S.Footers.Item(1).Range;$f.ParagraphFormat.Alignment=1;$f.Fields.Add($f,33)|Out-Null
function Get-InsertRange { $p=[Math]::Max(0,$D.Content.End-1); $D.Range($p,$p) }
function T([string]$x,[int]$a=3,[int]$z=11,[bool]$b=$false,[int]$after=5){$r=Get-InsertRange;$r.Text="$x`r";$r.Font.Name='Times New Roman';$r.Font.Size=$z;$r.Font.Bold=if($b){1}else{0};$r.ParagraphFormat.Alignment=$a;$r.ParagraphFormat.SpaceAfter=$after;return $r}
function AddHeading([string]$x,[int]$l=1){$size=12;if($l -eq 1){$size=15};T $x 0 $size $true 7|Out-Null}
function B([string[]]$x){$x|%{$r=T ('•  '+$_) 3 10 $false 3;$r.ParagraphFormat.LeftIndent=18;$r.ParagraphFormat.FirstLineIndent=-12}}
function Grid([string[]]$head,[object[][]]$rows){$r=Get-InsertRange;$t=$D.Tables.Add($r,$rows.Count+1,$head.Count);$t.Borders.Enable=1;$t.Range.Font.Name='Times New Roman';$t.Range.Font.Size=9;for($c=1;$c -le $head.Count;$c++){$t.Cell(1,$c).Range.Text=$head[$c-1];$t.Cell(1,$c).Range.Font.Bold=1};for($i=0;$i -lt $rows.Count;$i++){for($c=0;$c -lt $head.Count;$c++){$t.Cell($i+2,$c+1).Range.Text=[string]$rows[$i][$c]}};$t.Rows.AllowBreakAcrossPages=0;T '' 0 3 $false 2|Out-Null}
function Fig([string]$label,[string[]]$boxes){Grid @('Input / actor','Flow','Processing','Output') @(@($boxes[0],$boxes[1],$boxes[2],$boxes[3]));T $label 1 10 $false 6|Out-Null}
function Shot([string]$name,[string]$caption){$p=Join-Path $root $name;if(Test-Path $p){$r=Get-InsertRange;$i=$D.InlineShapes.AddPicture($p,$false,$true,$r);$i.Width=185};T $caption 1 10 $false 5|Out-Null}
function Next {$r=Get-InsertRange;$r.InsertBreak(7)}
function Page([scriptblock]$body,[bool]$last=$false){$null=&$body;if(-not $last){Next}}
Remove-Item Alias:H -Force
function H([string]$x,[int]$l=1){ AddHeading $x $l }

