Page {H 'APPENDIX F: REPORT VERIFICATION RECORD';T 'The report is generated first as an editable DOCX and then exported directly by Microsoft Word to PDF in the same folder. The PDF is therefore a rendering of the DOCX content. The generated report uses only source-supported feature descriptions, supplied screenshot assets and marked placeholders for unavailable institution-specific information.';H 'Submission Checklist' 2;B @('Confirm final PDF page count is between 50 and 52.','Inspect every page for clipped tables, isolated headings and unreadable screenshots.','Compare formatting, title-page sequence and certification wording against the college guideline when available.','Replace placeholders only with verified information.','Attach runtime test evidence before asserting Firebase/device behavior.') }
Page {H 'APPENDIX G: FINAL DOCUMENT NOTE';T 'This report is the final technical documentation package for Samay. It is intentionally transparent about evidence boundaries: source code and supplied visual assets support implementation claims; they do not establish live service outcomes. The report folder contains the editable source document and its PDF rendering.';T 'Before final academic submission, use the mandatory Engineering College Ajmer guideline document to replace the generic certificate/title formats and all listed placeholders. This preserves the accuracy of the technical report while allowing college-specific format compliance to be finalized from the authoritative document.';T 'End of Report' 1 11 $true 0|Out-Null } $true

# Save the completed report in both editable Word and PDF formats.
try {
    $D.Fields.Update() | Out-Null
    $D.SaveAs2($docx, 12) | Out-Null
    if (-not (Test-Path -LiteralPath $docx)) { throw "Word did not create DOCX: $docx" }
    $D.ExportAsFixedFormat($pdf, 17)
    if (-not (Test-Path -LiteralPath $pdf)) { throw "Word did not create PDF: $pdf" }
    Write-Host "Report created successfully:" -ForegroundColor Green
    Write-Host "DOCX: $docx"
    Write-Host "PDF : $pdf"
}
finally {
    if ($D -ne $null) { $D.Close($false) | Out-Null }
    if ($W -ne $null) { $W.Quit() | Out-Null }
    if ($D -ne $null) { [void][System.Runtime.InteropServices.Marshal]::ReleaseComObject($D) }
    if ($W -ne $null) { [void][System.Runtime.InteropServices.Marshal]::ReleaseComObject($W) }
    [GC]::Collect()
    [GC]::WaitForPendingFinalizers()
}
